<?php
require_once dirname(__DIR__,2).'/app/views.php'; require_role(['admin']);
$from=is_string($_GET['from']??null)?$_GET['from']:date('Y-01-01'); $to=is_string($_GET['to']??null)?$_GET['to']:date('Y-12-31');
foreach ([$from,$to] as $d) { $date=DateTimeImmutable::createFromFormat('!Y-m-d',$d); if (!$date || $date->format('Y-m-d')!==$d) {http_response_code(422);exit('Choose valid report dates.');} }
if ($from>$to) {http_response_code(422);exit('The start date must be before the end date.');}
$rows=sql("SELECT package_title,COUNT(*) bookings,SUM(travellers) travellers,SUM(CASE WHEN status IN ('confirmed','completed') THEN total_cents ELSE 0 END) value_cents,SUM(status='pending') pending,SUM(status='cancelled') cancelled FROM bookings WHERE travel_date BETWEEN ? AND ? GROUP BY package_title ORDER BY value_cents DESC",[$from,$to])->fetchAll();
if (($_GET['export']??'')==='csv') {
    header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="globetrek-report.csv"'); $f=fopen('php://output','w');
    fputcsv($f,['Adventure','Bookings','Travellers','Confirmed/completed value LKR','Pending','Cancelled'],',','"','');
    foreach ($rows as $r) { $title=$r['package_title']; if (preg_match('/^[=+@\-\t\r\n]/',$title)) $title="'".$title; fputcsv($f,[$title,$r['bookings'],$r['travellers'],number_format((int)$r['value_cents']/100,2,'.',''),$r['pending'],$r['cancelled']],',','"',''); } fclose($f); exit;
}
$totals=['bookings'=>0,'travellers'=>0,'value_cents'=>0]; foreach ($rows as $r) foreach ($totals as $k=>$v) $totals[$k]+=(int)$r[$k];
page_start('Business reports'); heading('ADMINISTRATION','A clearer view of the journey.'); ?>
<section class="container pb-5"><?php dashboard_nav('Reports'); ?><form class="filter-bar report-filter" method="get"><?php field('Travel dates from','from','date',$from,'required'); field('Through','to','date',$to,'required'); ?><button class="btn btn-primary">Update report</button><button class="btn btn-outline-dark" name="export" value="csv">Download CSV ↓</button></form><div class="stats-grid"><div class="stat"><span>Bookings (all statuses)</span><strong><?= $totals['bookings'] ?></strong></div><div class="stat"><span>Travellers (all statuses)</span><strong><?= $totals['travellers'] ?></strong></div><div class="stat"><span>Confirmed / completed value</span><strong class="money-stat"><?= money($totals['value_cents']) ?></strong></div></div><p class="muted">Reports use travel dates. Booking value is not payment received; this platform does not collect payments. Cancelled and pending bookings are excluded from value totals.</p><div class="surface table-responsive"><table class="table"><thead><tr><th>Adventure</th><th>Bookings</th><th>Travellers</th><th>Pending</th><th>Cancelled</th><th>Booking value</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?= e($r['package_title']) ?></td><td><?= (int)$r['bookings'] ?></td><td><?= (int)$r['travellers'] ?></td><td><?= (int)$r['pending'] ?></td><td><?= (int)$r['cancelled'] ?></td><td><?= money($r['value_cents']) ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$rows): ?><p>No bookings in this date range.</p><?php endif; ?></div></section>
<?php page_end(); ?>
